-- Pre-patch demon invasion: zones, map marker world states, creature roles and level scaling

-- Demon invasion: Northern Barrens is zone 17 (zone 10 is Duskwood)
UPDATE `outdoorpvp_template` SET `ZoneList` = '16 17 440' WHERE `TypeId` = 17 AND `ScriptName` = 'outdoorpvp_demon_invasion_kal';

-- World states lighting the six pre-patch invasion markers on the world map
DELETE FROM `worldstate_template` WHERE `VariableID` BETWEEN 19701 AND 19706;
INSERT INTO `worldstate_template` (`VariableID`, `Type`, `ConditionID`, `Flags`, `DefaultValue`, `LinkedID`, `Comment`) VALUES
(19701, 1, 0, 65536, 0, 0, 'Demon invasion map marker: Azshara'),
(19702, 1, 0, 65536, 0, 0, 'Demon invasion map marker: Dun Morogh'),
(19703, 1, 0, 65536, 0, 0, 'Demon invasion map marker: Hillsbrad Foothills'),
(19704, 1, 0, 65536, 0, 0, 'Demon invasion map marker: Northern Barrens'),
(19705, 1, 0, 65536, 0, 0, 'Demon invasion map marker: Tanaris'),
(19706, 1, 0, 65536, 0, 0, 'Demon invasion map marker: Westfall');

-- Role of each creature in the pre-patch demon invasion (1 demon, 2 elite worth three kills, 3 commander, 4 lieutenant, 5 demon lord)
CREATE TABLE IF NOT EXISTS `demon_invasion_creature` (
  `entry` INT UNSIGNED NOT NULL,
  `role` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `comment` VARCHAR(100) NOT NULL DEFAULT '',
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `demon_invasion_creature` WHERE `entry` BETWEEN 900001 AND 900099;
INSERT INTO `demon_invasion_creature` (`entry`, `role`, `comment`) VALUES
(900001, 1, 'Fel Invader (custom)'),
(900002, 1, 'Felstalker (custom)'),
(900003, 1, 'Fel Caster (custom)'),
(900004, 2, 'Infernal (custom)'),
(900010, 3, 'Commander (custom)'),
(900011, 4, 'Lieutenant (custom)'),
(900012, 4, 'Lieutenant (custom)'),
(900020, 5, 'Demon Lord (custom)');

-- Flame Fissure left by the demon lords
UPDATE `creature_template` SET `ScriptName` = 'npc_demon_invasion_flame_fissure' WHERE `entry` = 110023;

